#define spritePointerDef(pointer, base_tile_id, p1, p2, p3, p4) pointer & 0xff, pointer >> 8, base_tile_id, \
(p4 << 6) | (p3 << 4) | (p2 << 2) | p1
#define spriteTile(posX, posY, palette, tile_id_is_relative, priority, flipX, flipY, tile_id) \
posX, posY, (flipY << 7) | (flipX << 6) | (priority << 5) | ((tile_id_is_relative << 2) << 2) | palette, tile_id


